import{_ as r,C as e,o as d,c as i,a6 as o,E as a,w as l}from"./chunks/framework.BHBQfcoO.js";const m=JSON.parse('{"title":"Connection Overlay","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/connectivity.md","filePath":"configuration/connectivity.md"}'),c={name:"configuration/connectivity.md"};function h(p,t,g,u,f,y){const n=e("CardDemo"),s=e("ClientOnly");return d(),i("div",null,[t[0]||(t[0]=o(`<h1 id="connection-overlay" tabindex="-1">Connection Overlay <a class="header-anchor" href="#connection-overlay" aria-label="Permalink to &quot;Connection Overlay&quot;">​</a></h1><blockquote><p><strong>Full-screen overlay shown whenever Home Assistant loses its WebSocket connection</strong></p></blockquote><p>LCARdS can display a full-screen overlay when your browser loses its connection to Home Assistant. This is particularly useful for kiosk displays: instead of silently going stale the dashboard makes it immediately clear that it is offline, and snaps back to normal once the connection is restored.</p><p>The feature is configured from the <strong>Connectivity</strong> tab in the <a href="./">LCARdS Config Panel</a>.</p><hr><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>LCARdS monitors the HA WebSocket connection inside the browser. When the connection drops it waits a short tolerance window (default 2.5 s) before showing the overlay; brief blips during HA startup or network handoffs are absorbed silently. When the connection comes back the overlay is removed (optionally showing a brief confirmation banner first).</p><p>The overlay sits on top of the entire dashboard at the highest z-index so it is never obscured by HA&#39;s own UI.</p><div class="tip custom-block"><p class="custom-block-title">Alert mode co-existence</p><p>The connection overlay is automatically <strong>suppressed</strong> while any alert mode other than the baseline (<code>green_alert</code>) is active. Alert mode already implies a deliberate full-screen takeover, so the two overlays never compete.</p></div><hr><h2 id="setting-up" tabindex="-1">Setting up <a class="header-anchor" href="#setting-up" aria-label="Permalink to &quot;Setting up&quot;">​</a></h2><p>Open <strong>Config Panel → Connectivity</strong>.</p><p>Changes made in the panel are <strong>not live until you click Save</strong>. Use the <strong>Test Controls</strong> section at the bottom to preview how the overlay looks with your current settings at any time, no save required.</p><hr><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enable connection overlay</strong></td><td>On</td><td>Master switch. When off, no overlay is shown on disconnect.</td></tr><tr><td><strong>Allow user to dismiss</strong></td><td>On</td><td>Let the user click the overlay backdrop to close it manually. Useful if you want a &quot;confirm you know it&#39;s offline&quot; interaction rather than a pure indicator.</td></tr><tr><td><strong>Disconnect tolerance</strong></td><td>2500 ms</td><td>How long to wait after a disconnect event before showing the overlay. Brief blips during HA startup or mobile network handoffs are silently absorbed. Set to 0 to show immediately.</td></tr></tbody></table><hr><h2 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h2><p>The <strong>Messages</strong> section (collapsed by default) controls what is shown on screen when the connection is lost and when it is restored.</p><h3 id="display-style" tabindex="-1">Display style <a class="header-anchor" href="#display-style" aria-label="Permalink to &quot;Display style&quot;">​</a></h3><p>Choose between two modes:</p><p><strong>Simple text</strong>: LCARdS renders styled text directly on top of the effect layers. No card required. Use the typography controls below to set the message content, colour, font, size, weight, and casing.</p><p><strong>Custom card (YAML)</strong>: Provide any valid HA card YAML. LCARdS renders the card centred in the overlay, letting you use your own button cards, custom components, or LCARdS cards as the disconnect screen. You control position, width, and height.</p><hr><h3 id="simple-text-mode" tabindex="-1">Simple text mode <a class="header-anchor" href="#simple-text-mode" aria-label="Permalink to &quot;Simple text mode&quot;">​</a></h3><h4 id="connection-lost" tabindex="-1">Connection Lost <a class="header-anchor" href="#connection-lost" aria-label="Permalink to &quot;Connection Lost&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Message text</strong></td><td><code>Connection Lost</code></td><td>The string displayed while disconnected.</td></tr><tr><td><strong>Text colour</strong></td><td><code>#93e1ff</code></td><td>Any CSS colour value or LCARdS theme token.</td></tr><tr><td><strong>Font</strong></td><td><code>Antonio</code></td><td>Font family: choose from the font selector or type any web-safe font name.</td></tr><tr><td><strong>Size</strong></td><td><code>26 px</code></td><td>Font size in pixels.</td></tr><tr><td><strong>Weight</strong></td><td><code>400</code></td><td>CSS font-weight: e.g. <code>400</code>, <code>700</code>, <code>bold</code>.</td></tr><tr><td><strong>Transform</strong></td><td><code>UPPERCASE</code></td><td><code>UPPERCASE</code>, <code>Title Case</code>, or <code>None</code>.</td></tr></tbody></table><h4 id="connection-restored" tabindex="-1">Connection Restored <a class="header-anchor" href="#connection-restored" aria-label="Permalink to &quot;Connection Restored&quot;">​</a></h4><p>An optional confirmation banner shown briefly after the connection returns.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Show reconnect message</strong></td><td>Off</td><td>Enable the banner. When off, the overlay simply disappears on reconnect.</td></tr><tr><td><strong>Message text</strong></td><td><code>Connection Restored</code></td><td>Confirmation string.</td></tr><tr><td><strong>Text colour</strong></td><td><code>#4caf50</code></td><td>Defaults to a calm green.</td></tr><tr><td><strong>Font / Size / Weight / Transform</strong></td><td>Same as disconnect message</td><td>Independent per-field controls.</td></tr><tr><td><strong>Auto-dismiss after</strong></td><td><code>3 s</code></td><td>How long the reconnect banner stays visible (1–30 s).</td></tr></tbody></table><hr><h3 id="custom-card-mode" tabindex="-1">Custom card mode <a class="header-anchor" href="#custom-card-mode" aria-label="Permalink to &quot;Custom card mode&quot;">​</a></h3><h4 id="connection-lost-card" tabindex="-1">Connection Lost Card <a class="header-anchor" href="#connection-lost-card" aria-label="Permalink to &quot;Connection Lost Card&quot;">​</a></h4><p>Paste any valid HA card YAML into the editor. The card is rendered on top of the effect layers.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>YAML editor</strong></td><td><em>(empty)</em></td><td>Card config in YAML: same format as Lovelace card config.</td></tr><tr><td><strong>Position</strong></td><td><code>center</code></td><td>Where to anchor the card within the overlay (<code>top-left</code>, <code>center</code>, <code>bottom-right</code>, etc.).</td></tr><tr><td><strong>Width</strong></td><td><code>auto</code></td><td>CSS width: e.g. <code>400px</code>, <code>40vw</code>, <code>auto</code>.</td></tr><tr><td><strong>Height</strong></td><td><code>auto</code></td><td>CSS height: e.g. <code>300px</code>, <code>30vh</code>, <code>auto</code>.</td></tr></tbody></table><p><strong>Example (minimal LCARdS button card):</strong></p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:lcards-button</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;NO SIGNAL&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  card</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      background</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;theme:colors.ui.primary&quot;</span></span></code></pre></div>`,37)),a(s,null,{default:l(()=>[a(n,{src:"type%3A%20custom%3Alcards-button%0Atext%3A%0A%20%20label%3A%0A%20%20%20%20content%3A%20%22NO%20SIGNAL%22%0Astyle%3A%0A%20%20card%3A%0A%20%20%20%20color%3A%0A%20%20%20%20%20%20background%3A%20%22theme%3Acolors.ui.primary%22%0A"})]),_:1}),t[1]||(t[1]=o('<h4 id="connection-restored-card" tabindex="-1">Connection Restored Card <a class="header-anchor" href="#connection-restored-card" aria-label="Permalink to &quot;Connection Restored Card&quot;">​</a></h4><p>Paste optional card YAML to show when the connection comes back. Leave empty to fall back to the simple text reconnect message (if enabled) or no banner at all.</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>YAML editor</strong></td><td><em>(empty)</em></td><td>Card config shown on reconnect.</td></tr><tr><td><strong>Show reconnect message</strong></td><td>Off</td><td>Enable the card/banner.</td></tr><tr><td><strong>Auto-dismiss after</strong></td><td><code>3 s</code></td><td>How long the reconnect card stays visible.</td></tr></tbody></table><hr><h2 id="effect-layers" tabindex="-1">Effect Layers <a class="header-anchor" href="#effect-layers" aria-label="Permalink to &quot;Effect Layers&quot;">​</a></h2><p>The <strong>Effect Layers</strong> section (collapsed by default) controls the full-screen visual effects composited behind the message.</p><p>LCARdS uses three independent layer slots that stack from back to front:</p><table tabindex="0"><thead><tr><th>Slot</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Canvas Effect</strong></td><td>Animated pixel art drawn on a <code>&lt;canvas&gt;</code>: static noise, glitch, scanlines, pixelate</td><td><code>static</code> at 45 % opacity</td></tr><tr><td><strong>Colour Overlay</strong></td><td>Solid or gradient colour div over the canvas</td><td><code>color-tint</code> at <code>rgba(0,0,0,0.55)</code></td></tr><tr><td><strong>Backdrop Filter</strong></td><td>CSS <code>backdrop-filter</code> applied to everything below: blur, saturate, grayscale, etc.</td><td>None</td></tr></tbody></table><h3 id="configuring-a-slot" tabindex="-1">Configuring a slot <a class="header-anchor" href="#configuring-a-slot" aria-label="Permalink to &quot;Configuring a slot&quot;">​</a></h3><p>For each slot, choose a <strong>preset</strong> from the dropdown. Available presets are pulled from the registered SEM catalog (built-in presets plus any registered by installed content packs).</p><p>Once you pick a preset, additional parameter fields appear for that preset&#39;s adjustable options:</p><table tabindex="0"><thead><tr><th>Preset</th><th>Slot</th><th>Key parameters</th></tr></thead><tbody><tr><td><code>static</code></td><td>Canvas</td><td>Opacity, Grain Scale, Tint Color, Tint Strength</td></tr><tr><td><code>pixelate</code></td><td>Canvas</td><td>Pixel Size, Opacity, Light Variance, Base Lightness, Tint Color, Tint Strength</td></tr><tr><td><code>glitch</code></td><td>Canvas</td><td>Intensity, Max Shift, Band Height, Opacity, FPS</td></tr><tr><td><code>scanlines</code></td><td>Canvas</td><td>Line Height, Opacity, Scroll Speed</td></tr><tr><td><code>color-tint</code></td><td>Colour</td><td>Tint Color (any CSS colour / rgba)</td></tr><tr><td><code>vignette</code></td><td>Colour</td><td>Opacity</td></tr><tr><td><code>blur</code></td><td>Backdrop</td><td>Blur Amount (e.g. <code>8px</code>)</td></tr><tr><td><code>saturate</code></td><td>Backdrop</td><td>Amount (e.g. <code>200%</code>)</td></tr><tr><td><code>grayscale</code></td><td>Backdrop</td><td>Amount (e.g. <code>100%</code>)</td></tr><tr><td><code>contrast</code></td><td>Backdrop</td><td>Amount (e.g. <code>150%</code>)</td></tr><tr><td><code>hue-rotate</code></td><td>Backdrop</td><td>Angle (e.g. <code>180deg</code>)</td></tr></tbody></table><p>Set a slot to <strong>None (disabled)</strong> to turn it off entirely. You can mix and match freely: for example, <code>grayscale</code> backdrop + <code>color-tint</code> colour overlay gives a desaturated-with-tint look without any canvas animation.</p><hr><h2 id="test-controls" tabindex="-1">Test Controls <a class="header-anchor" href="#test-controls" aria-label="Permalink to &quot;Test Controls&quot;">​</a></h2><p>Use <strong>Simulate Disconnect</strong> to trigger the overlay immediately with your current unsaved settings. The dashboard continues to run normally behind it; HA is not actually disconnected.</p><p>Click <strong>Clear Test</strong> to dismiss it. The test state is indicated by the button states: <strong>Simulate Disconnect</strong> disables while the test is active.</p><div class="tip custom-block"><p class="custom-block-title">Workflow tip</p><p>Adjust a setting → click <strong>Simulate Disconnect</strong> → evaluate → adjust → repeat. When happy, click <strong>Save</strong>.</p></div><hr><h2 id="scope-and-per-device-overrides" tabindex="-1">Scope and per-device overrides <a class="header-anchor" href="#scope-and-per-device-overrides" aria-label="Permalink to &quot;Scope and per-device overrides&quot;">​</a></h2><p>The <strong>Connectivity</strong> tab uses the same three-level scope waterfall as the <a href="./sounds.html">Sounds</a> tab:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Device  →  User  →  Global</span></span></code></pre></div><p>Use the <strong>scope selector</strong> at the top of the tab to choose which level you are configuring:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Who it applies to</th></tr></thead><tbody><tr><td><strong>Global</strong></td><td>Every user and device (the installation-wide default)</td></tr><tr><td><strong>User</strong></td><td>Your HA user account, on any device</td></tr><tr><td><strong>Device</strong></td><td>This specific browser, regardless of which HA user is logged in</td></tr></tbody></table><p>Each field shows a small badge indicating where its current value comes from. If a field has an override at the selected scope, a <strong>×</strong> button lets you clear that override and fall back to the level below.</p><p><strong>Save</strong> writes only the fields you actually changed in this editing session to the selected scope. Unchanged fields are not written, so they continue to resolve from lower scopes as intended. The <strong>Clear</strong> button removes all overrides stored at that scope; the resolved value then falls through to the next level.</p><h3 id="admin-editing-another-device-or-user" tabindex="-1">Admin: editing another device or user <a class="header-anchor" href="#admin-editing-another-device-or-user" aria-label="Permalink to &quot;Admin: editing another device or user&quot;">​</a></h3><p>Admins can select a different device or user from the scope selector dropdown. Settings saved that way are pushed directly to that scope in storage, and the affected device picks them up automatically within seconds, no page reload required on the target device.</p><p>If you have the Config Panel open on a device when another admin remotely updates its settings:</p><ul><li>If you have no unsaved edits, the panel refreshes its badge state automatically.</li><li>If you have unsaved edits, a blue banner appears: &quot;Settings were updated from another device&quot;, with a <strong>Discard edits &amp; refresh</strong> button. Your in-progress changes are preserved until you decide.</li></ul><h3 id="reload-controls" tabindex="-1">Reload controls <a class="header-anchor" href="#reload-controls" aria-label="Permalink to &quot;Reload controls&quot;">​</a></h3><p>The action row includes two admin-only broadcast buttons:</p><table tabindex="0"><thead><tr><th>Button</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Reload Config</strong></td><td>All connected browsers re-read their connection overlay config from storage. Non-disruptive: no page reload. Use this to push a stored config change to a device that was offline when you saved.</td></tr><tr><td><strong>Reload Pages</strong></td><td>All connected browsers call <code>window.location.reload()</code>. Use this as a last resort if a device&#39;s JS state has drifted (rare).</td></tr></tbody></table><hr><h2 id="upgrading-existing-stored-settings" tabindex="-1">Upgrading: existing stored settings <a class="header-anchor" href="#upgrading-existing-stored-settings" aria-label="Permalink to &quot;Upgrading: existing stored settings&quot;">​</a></h2><p>If you set up connectivity settings before field-level saving was introduced, your device/user/global storage may contain all 25 fields at a single scope even though you only intended to override a few. <strong>This is harmless</strong>: values are all correct and the waterfall applies them in order.</p><p>If you want to clean up and have only your intentional overrides at device scope:</p><ol><li>Open <strong>Config Panel → Connectivity → Device</strong> tab for the device in question.</li><li>Note which settings differ from your global/user defaults.</li><li>Click <strong>Clear device</strong> to remove all device-scope overrides.</li><li>Re-save only the settings you actually want to pin at device scope.</li></ol><p>After this, only those fields will show a <strong>device</strong> badge; others will show <strong>global</strong> or <strong>user</strong> indicating they resolve from a higher scope.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Configuration overview</a>: all Config Panel tabs</li><li><a href="./users-devices.html">Users &amp; Devices</a>: manage stored per-device and per-user overrides</li><li><a href="./../architecture/subsystems/screen-effects.html">Screen Effect System</a>: developer reference for effect presets and the SEM layer</li><li><a href="./../architecture/subsystems/connection-overlay.html">Connection Overlay Service</a>: architecture reference</li></ul>',42))])}const v=r(c,[["render",h]]);export{m as __pageData,v as default};
